mapper.select:
select count(1)
from sys_user_tenant
where user_id = #{userId}
  and tenant_id = #{tenantId}

select u.id, u.username, u.display_name, u.role_id, r.code role_code, r.name role_name, u.enabled, u.created_at
from sys_user u inner join sys_role r on r.id = u.role_id
where u.deleted = 0
and (u.username like concat('%', #{keyword}, '%') or u.display_name like concat('%', #{keyword}, '%'))
and u.role_id = #{roleId}
and u.enabled = #{enabled}
order by u.created_at desc, u.id
limit #{offset}, #{pageSize}

select count(1) from sys_user u where u.deleted = 0
and (u.username like concat('%', #{keyword}, '%') or u.display_name like concat('%', #{keyword}, '%'))
and u.role_id = #{roleId}
and u.enabled = #{enabled}
